import re, xml.etree.ElementTree as ET
from collections import Counter, defaultdict
NS='{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
ss=[''.join(t.text or '' for t in si.iter(NS+'t')) for si in ET.parse('xl/sharedStrings.xml').getroot()]
def col(ref):
    n=0
    for ch in re.match(r'([A-Z]+)',ref).group(1): n=n*26+ord(ch)-64
    return n-1
def load(f):
    root=ET.parse('xl/worksheets/'+f).getroot(); rows=[]
    for row in root.iter(NS+'row'):
        cells={}
        for c in row.iter(NS+'c'):
            v=c.find(NS+'v')
            if v is None: continue
            cells[col(c.get('r'))]=ss[int(v.text)] if c.get('t')=='s' else v.text
        if cells: rows.append([cells.get(i,'') for i in range(max(cells)+1)])
    return rows
for f,name in [('sheet1.xml','INTERIOR'),('sheet2.xml','OUTDOOR')]:
    rows=load(f); hdr=rows[0]; data=rows[1:]
    print('#'*30,name,'righe dati:',len(data))
    print('HEADER:', [f'{i}:{h}' for i,h in enumerate(hdr)])
    for i,h in enumerate(hdr):
        vals=[(r[i] if i<len(r) else '').strip() for r in data]
        c=Counter(vals); empty=c.get('',0)
        uniq=len([k for k in c if k])
        print(f'\n-- [{i}] {h!r} | vuoti={empty} distinti={uniq}')
        if uniq<=25:
            for k,n in c.most_common():
                print(f'     {k!r}: {n}')
        else:
            for k,n in c.most_common(8): print(f'     {k!r}: {n}')
            print('     ...')
EOF
